def anglais(texte):
    """Traduction anglaise d'un texte français du catalogue (avec sa phrase de fin : « Saisir 0 s'il n'y en a pas », N/A d'une
    catégorie du scope 3)."""
    for fin, fin_en in ((ZERO, ZERO_EN), (S3_NA, S3_NA_EN)):
        if texte.endswith(fin):
            return anglais(texte[: -len(fin)]) + fin_en
    if texte not in T:
        raise KeyError("Missing translation (referentiel/bibliotheque/catalogue_anglais.py): " + texte)
    return T[texte]
